"""Fixed-point logarithms: the complete table, interpolation and API contract."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='고정소수점 · 조회표·수치 근사',
                     sections=sections, questions=questions))


add('lib/math/int_log.c', '정수 로그 구현 전체: 256개 표와 선형 보간',
    '정수 입력의 로그를 소수부24비트의 고정소수점으로 근사합니다.',
    'intlog2는 최상위1비트 위치를 정수 지수로 분리하고 정규화한 유효숫자의 상위8개 가변 비트로 표를 조회합니다. 남은23비트는 다음 표 값까지 선형 보간하는 데 사용합니다. intlog10은 intlog2에 고정소수점 log10(2)를 곱합니다.',
    '양의 u32 입력을 사용합니다. 반환형이 unsigned int라고 소수부가 없는 정수 로그인 것은 아닙니다.2^24로 나눠야 로그 단위의 값을 얻습니다.',
    [('파일 전체 구성', 'LGPL-2.1-or-later 식별,저작권,bitops/export/int_log/kernel/types 및 asm/bug 헤더,256개 unsigned short 상수 표,intlog2와 intlog10,각 export로 구성됩니다. 별도 초기화·동적 할당·가변 전역 상태는 없습니다.'),
     ('표 전체의 의미', 'logtable[i]는 log2(1+i/256)*2^16을 반올림한 값과256개 모두 일치합니다. 첫 값0,마지막0xff47이고 단조 증가합니다. 내부 표는 소수부16비트,최종 출력은24비트여서 표 값을8비트 왼쪽 이동합니다. 최대 인접 차이는369이며 마지막에서 가상의2.0 끝점까지 차이도 고려합니다.'),
     ('정규화와 인덱스', 'msb=fls(value)-1은0기반 최상위 비트 위치입니다. value<<(31-msb)로 최상위 비트를31번에 맞춥니다. significand>>23의 최상위1은 고정이므로 %256으로 제거하고0..255의 인덱스를 얻습니다. 입력8은 msb3,significand0x80000000,index0이라 정확히3<<24를 반환합니다.'),
     ('보간과 마지막 구간', '하위23비트에 인접 표 값의 차이를 곱하고15비트 오른쪽 이동합니다.23비트 비율을 적용하면서 표의16비트 소수부를24비트로 바꾸므로23-8=15입니다. index255의 다음 인덱스는0으로 감기지만 차이에 &0xffff를 적용하여 가상의 표 값65536과의 차이185를 얻습니다. 끝 구간이 음의 기울기가 되는 것은 아닙니다.'),
     ('곱의 폭과 오차', '최대 하위값0x7fffff와 최대 표 차이369에 대해 (2^23-1)*369<2^32입니다. 따라서 이 보간 곱은32비트 unsigned 범위 안입니다. 표 양자화,로그 곡선의 선형 보간,우측 시프트 절단 때문에 일반 입력에 정확한 실수 로그를 보장하지 않습니다.'),
     ('밑10 변환', 'intlog10은 intlog2 결과를 u64 log에 저장한 뒤646456993을 곱하고31비트 이동합니다. 상수는 log10(2)를2^31 배율로 근사한 것입니다. 곱을 u64로 수행하는 점이 중요하며 반환 배율은 여전히2^24입니다.1000처럼 정확한 로그가 정수인 입력도 구현 결과는3<<24와 조금 다를 수 있습니다.'),
     ('0 입력과 진단', '두 함수 모두0이면 WARN_ON(1) 후0을 반환합니다. log(0)의 수학적 값이0이라는 뜻이 아닙니다. 정상 입력1의 로그도0이므로 반환값만으로 잘못된0 입력을 판별할 수 없습니다. intlog10의0 분기는 intlog2 호출보다 앞에 있습니다.'),
     ('CS와 검증 범위', '정규화,지수·유효숫자 분리,조회표의 공간/정확도 절충,선형 보간,고정소수점 스케일 변환을 연결합니다. 독립 실수 로그와의 표본 오차 및2의 거듭제곱 정확값을 확인할 수 있지만 유한 표본의 최대 오차를 전체 u32 입력의 증명된 상한이라고 말하면 안 됩니다.')],
    [('intlog2(8)의 반환값을 로그 단위로 읽는 방법은?', '반환값을2^24로 나누면3이다', '반환값을 그대로 정수3으로 읽는다', 'msb3을24비트 왼쪽 이동한50,331,648을 반환합니다. 소수부24비트 배율을 고려해야 합니다.'),
     ('보간의 마지막 표 구간은 감소하는 구간인가?', '아니다. 마스크로 가상 끝점65536까지의 양의 차이를 구한다', '그렇다. 다음 표 값0을 그냥 빼서 감소한다', '0-0xff47에 &0xffff를 적용하면185입니다. 표의 순환 인덱스와 수학적 끝점 처리를 함께 읽어야 합니다.'),
     ('0 반환만으로 입력이 유효했다고 판단할 수 있는가?', '없다. 잘못된 입력0과 정상 입력1 모두0을 반환한다', '있다. 잘못된 입력은 음수를 반환한다', '반환형은 unsigned이며0 입력은 경고 후0입니다. 유효 입력 전제는 호출자가 지켜야 합니다.'),
     ('intlog10이 u64 중간값을 쓰는 이유는?', '스케일 변환 상수와의 곱을 넓은 타입에서 계산하기 위해서다', '최종 반환형도 반드시128비트여야 하기 때문이다', 'intlog2의 스케일된 결과에646456993을 곱하므로32비트 중간 곱으로는 부족합니다. 최종 반환은 unsigned int입니다.')])

add('include/linux/int_log.h', '정수 로그 헤더 전체: 고정소수점 입력을 해석하는 계약',
    '정수 인자 API로 소수 비율의 로그를 계산하는 스케일 보정 방법입니다.',
    'intlog2와 intlog10은 비영 u32를 받아 로그의2^24배인 unsigned int를 반환합니다. 문서 예제는 원래 값을 정수로 스케일한 뒤 로그의 상수항을 빼는 방법을 설명합니다.',
    '1.5를 함수에 직접 전달하는 대신 intlog2(3)-2^24를 사용합니다. 문서의 intlog2(1.5)는 수학적 설명이며 실제 함수의 인자 타입은 u32입니다.',
    [('파일 전체', 'LGPL-2.1-or-later,저작권, __LINUX_INT_LOG_H guard,types.h 포함,두 함수의 상세 주석과 extern 선언,#endif가 전부입니다. 표와 계산 루프는 구현 파일에 있습니다.'),
     ('밑2 보정', '원래 값v를2^x배 하여 정수로 전달했다면 intlog2(v*2^x)-x*2^24로 보정합니다.1.5의 경우3을 전달하고1*2^24를 빼면 약0.585*2^24입니다. 곱한 입력이 u32 범위에 들어가고0으로 절단되지 않는지도 확인해야 합니다.'),
     ('밑10 보정', 'intlog10은10^x 스케일에 대해 x*2^24를 뺍니다.2배 스케일의 보정값을 밑10에서도 그대로1*2^24로 쓰면 잘못입니다. 헤더는1000의 결과조차 정확히3<<24가 아닐 수 있다고 명시합니다.'),
     ('음수 로그와 타입', '0<v<1의 로그는 음수지만 함수 반환형은 unsigned입니다. 스케일 보정 뺄셈 전에 충분히 넓은 signed 타입으로 변환하면 unsigned 언더플로를 피할 수 있습니다. 예컨대0.5의 로그를 intlog2(1)-2^24로 표현할 때 C의 통상 산술 변환을 확인해야 합니다. 헤더의 수학식은 모든 C 타입 조합의 안전성 보장이 아닙니다.')],
    [('intlog2(1.5)를 C 호출로 그대로 쓰면 문서 예제와 같은가?', '아니다. 인자는 u32라 소수 부분을 직접 표현하지 못한다', '그렇다. 선언이 실수 입력을 자동 지원한다', '문서의 수식은 스케일 보정 설명입니다. 실제 예제는 intlog2(3)에서2^24를 빼는 방식으로 구현합니다.'),
     ('0.5의 로그를 보정할 때 주의할 점은?', '음수 결과를 담을 signed 계산 타입을 준비해야 한다', 'unsigned 반환이면 음수도 자동으로 정확히 표현된다', '함수 반환값 그대로 unsigned 뺄셈하면 순환할 수 있습니다. 먼저 충분히 넓은 signed 타입으로 바꾼 뒤 스케일을 보정합니다.'),
     ('intlog10에서10^x로 스케일한 입력의 보정항은?', 'x*2^24', 'x*2^31', '반환값의 로그 배율은2^24입니다. 구현의 변환 상수 배율2^31과 혼동하지 않습니다.')])
